package com.gstory.flutter_unionad.splashad

import android.content.Context
import org.json.JSONException
import org.json.JSONObject
import android.util.Log;

class AdsConfig {

    companion object{
        val yinbiao = "{\"cypher\":4,\"message\":\"\"}"
        val gaokao = "{\"cypher\":4,\"message\":\"\"}"
        val xingainianyingyu = "{\"cypher\":4,\"message\":\"\"}"
        val tangshi = "{\"cypher\":4,\"message\":\"\"}"
        fun getAdsConfig (context: Context): JSONObject {
            val packageName = context.packageName

            var configJsonObj: JSONObject? = null
            try {
                if(packageName == "com.yyybabc"){
                    configJsonObj = JSONObject(yinbiao);
                }else if(packageName == "com.yuyao.gaokao"){
                    configJsonObj = JSONObject(gaokao);
                }else if(packageName == "com.yuyao.xingainianyingyu"){
                    configJsonObj = JSONObject(xingainianyingyu);
                }else if(packageName == "com.yuyao.tangshi"){
                    configJsonObj = JSONObject(xingainianyingyu);
                }
            } catch (e: JSONException) {
                configJsonObj = JSONObject();
            }

            Log.i("TAG", "广告配置信息");
            Log.i("TAG", packageName);
            Log.i("TAG", configJsonObj.toString());


            return configJsonObj!!
        }
    }
}